SELECT CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 14 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, SUM(CASE WHEN channel = 'mobile' THEN discount ELSE 0 END) AS mobile_discount, ROUND(STDDEV(amount), 2) AS stddev_amount, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM orders GROUP BY CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 14 THEN 'mid' ELSE 'low' END ORDER BY mobile_discount DESC
